      din     : in     std_logic_vector (15 downto 0);
      n_pixel : in     std_logic_vector (15 downto 0);
      reset   : in     std_logic;
      rgb     : in     std_logic_vector (23 downto 0);
      trig    : in     std_logic;
      sdata   : out    std_logic
   );

