LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
use ieee.std_logic_unsigned.all;
library work;
use work.utilities.all;
 
architecture fsm of ledstrip_ctrl is

   -- Architecture Declarations
   signal bit_timer: std_logic_vector(15 downto 0);
   signal reset_timer: std_logic_vector(7 downto 0);
   signal bit_next, bit_0,bit_1,bit_reset: std_logic;
   signal txreg: std_logic_vector(rgb'range);
   signal cnt: std_logic_vector(7 downto 0);
   signal pix_cnt: std_logic_vector(15 downto 0);
   signal led_data: std_logic;
   signal data_sreg: std_logic_vector(din'range);
   
   constant f_mhz_c: integer := core_clk_freq_g / 1_000_000;
   constant bit0_c: integer := (40 * f_mhz_c)/100;
   constant bit1_c: integer := (85 * f_mhz_c)/100;
   constant bit_c: integer := (125 * f_mhz_c)/100;

   type state_type is (
      s0,
      s1,
      s2,
      s3
   );
 
   -- Declare current and next state signals
   signal current_state : state_type;
   signal next_state : state_type;

begin

   -----------------------------------------------------------------
   clocked_proc : process ( 
      clk
   )
   -----------------------------------------------------------------
   begin
      if (clk'event and clk = '1') then
         if (reset = '1') then
            current_state <= s0;
         else
            current_state <= next_state;
            -- Default Assignment To Internals
            led_data <= '0';

            -- Combined Actions
            case current_state is
               when s0 => 
                  if (trig = '1') then 
                     data_sreg <= din;
                     pix_cnt <= (0=>'1',others => '0');
                  end if;
               when s1 => 
                  led_data <= '1';
                  if (txreg(txreg'left) = '0' and bit_0 = '1') then 
                     cnt <= cnt+1;
                  elsif (txreg(txreg'left) = '1' and bit_1 = '1') then 
                     cnt <= cnt+1;
                  end if;
               when s2 => 
                  if (bit_next = '1' and cnt >= 24 and pix_cnt >= n_pixel) then 
                     txreg <= rgb;
                     cnt <= (others => '0');
                     pix_cnt <= (0=>'1',others => '0');
                  elsif (bit_next = '1' and cnt >= 24) then 
                     txreg <= rgb;
                     cnt <= (others => '0');
                     pix_cnt <= pix_cnt+1;
                     data_sreg <= '0' & data_sreg(data_sreg'left downto 1);
                  elsif (bit_next = '1') then 
                     txreg <= txreg(txreg'left-1 downto 0) & '0';
                     --pix_cnt <= pix_cnt+1;
                  end if;
               when s3 => 
                  if data_sreg(0) = '1' then
                       txreg <= rgb;
                  else
                       txreg <= (others => '0');
                  end if;
                  cnt <= (others => '0');
               when others =>
                  null;
            end case;
         end if;
      end if;
   end process clocked_proc;
 
   -----------------------------------------------------------------
   nextstate_proc : process ( 
      bit_0,
      bit_1,
      bit_next,
      cnt,
      current_state,
      n_pixel,
      pix_cnt,
      trig,
      txreg
   )
   -----------------------------------------------------------------
   begin
      case current_state is
         when s0 => 
            if (trig = '1') then 
               next_state <= s3;
            else
               next_state <= s0;
            end if;
         when s1 => 
            if (txreg(txreg'left) = '0' and bit_0 = '1') then 
               next_state <= s2;
            elsif (txreg(txreg'left) = '1' and bit_1 = '1') then 
               next_state <= s2;
            else
               next_state <= s1;
            end if;
         when s2 => 
            if (bit_next = '1' and cnt >= 24 and pix_cnt >= n_pixel) then 
               next_state <= s0;
            elsif (bit_next = '1' and cnt >= 24) then 
               next_state <= s3;
            elsif (bit_next = '1') then 
               next_state <= s1;
            else
               next_state <= s2;
            end if;
         when s3 => 
            next_state <= s1;
         when others =>
            next_state <= s0;
      end case;
   end process nextstate_proc;
 
   -- Concurrent Statements
   sdata <= led_data;
   
   process(clk)
   begin
       if rising_edge(clk) then
         if reset = '1' then
            bit_timer <= (others => '0');
            reset_timer <= (others => '0');
        else
            if bit_next = '1' then
               bit_timer <= (others => '0');
               reset_timer <= reset_timer + 1;
               if bit_reset = '1' then
                    reset_timer <= (others => '0');
               end if;
           else
               bit_timer <= bit_timer+1;
           end if;
         end if;
      end if;
   end process;
   bit_next <= '1' when bit_timer = bit_c-1 else '0';
   bit_0 <= '1' when bit_timer = bit0_c-1 else '0';
   bit_1 <= '1' when bit_timer = bit1_c-1 else '0';
   bit_reset <= '1' when reset_timer = 49 else '0';
end fsm;
